package scanner

import (
	"bytes"
	"encoding/binary"
	"image"
	"image/jpeg"
	"os"
	"path/filepath"
	"testing"
	"time"
)

// Fixtures in testdata are generated by TestGenerateFixtures:
//
//	FE_GEN_FIXTURES=1 go test ./internal/scanner -run TestGenerateFixtures

func TestGenerateFixtures(t *testing.T) {
	if os.Getenv("FE_GEN_FIXTURES") == "" {
		t.Skip("set FE_GEN_FIXTURES=1 to regenerate testdata")
	}
	write := func(name string, b []byte) {
		if err := os.WriteFile(filepath.Join("testdata", name), b, 0o644); err != nil {
			t.Fatal(err)
		}
	}
	write("exif.jpg", buildExifJPEG(t, "2021:07:04 09:30:00", "TestCam X1"))
	write("clip.mp4", buildMP4(time.Date(2022, 3, 15, 18, 0, 0, 0, time.UTC), 0, false))
}

type ifdEntry struct {
	tag, typ uint16
	count    uint32
	data     []byte // inline when <= 4 bytes, else stored after the IFD
}

func buildTIFF(dateTime, model string) []byte {
	le := binary.LittleEndian
	ascii := func(s string) []byte { return append([]byte(s), 0) }
	rational := func(vals ...uint32) []byte {
		b := make([]byte, 0, 8*len(vals))
		for _, v := range vals {
			b = le.AppendUint32(b, v)
			b = le.AppendUint32(b, 1)
		}
		return b
	}
	u32 := func(v uint32) []byte { return le.AppendUint32(nil, v) }

	ifdSize := func(n int) int { return 2 + 12*n + 4 }
	var out bytes.Buffer
	out.Write([]byte("II*\x00"))
	out.Write(u32(8))

	// Layout: IFD0 | IFD0 data | ExifIFD | Exif data | GPSIFD | GPS data.
	writeIFD := func(start int, entries []ifdEntry) []byte {
		var ifd, data bytes.Buffer
		dataOff := start + ifdSize(len(entries))
		ifd.Write(binary.LittleEndian.AppendUint16(nil, uint16(len(entries))))
		for _, e := range entries {
			ifd.Write(le.AppendUint16(nil, e.tag))
			ifd.Write(le.AppendUint16(nil, e.typ))
			ifd.Write(u32(e.count))
			if len(e.data) <= 4 {
				v := make([]byte, 4)
				copy(v, e.data)
				ifd.Write(v)
			} else {
				ifd.Write(u32(uint32(dataOff + data.Len())))
				data.Write(e.data)
				if data.Len()%2 == 1 {
					data.WriteByte(0)
				}
			}
		}
		ifd.Write(u32(0))
		return append(ifd.Bytes(), data.Bytes()...)
	}

	modelB := ascii(model)
	dtB := ascii(dateTime)
	// Sizes are fixed by the entries, so offsets can be computed up front.
	ifd0Len := len(writeIFD(8, []ifdEntry{
		{0x0110, 2, uint32(len(modelB)), modelB}, {0x8769, 4, 1, u32(0)}, {0x8825, 4, 1, u32(0)},
	}))
	exifStart := 8 + ifd0Len
	exifIFD := writeIFD(exifStart, []ifdEntry{{0x9003, 2, uint32(len(dtB)), dtB}})
	gpsStart := exifStart + len(exifIFD)
	ifd0 := writeIFD(8, []ifdEntry{
		{0x0110, 2, uint32(len(modelB)), modelB},
		{0x8769, 4, 1, u32(uint32(exifStart))},
		{0x8825, 4, 1, u32(uint32(gpsStart))},
	})
	gpsIFD := writeIFD(gpsStart, []ifdEntry{
		{0x0001, 2, 2, ascii("N")},
		{0x0002, 5, 3, rational(48, 51, 24)},
		{0x0003, 2, 2, ascii("E")},
		{0x0004, 5, 3, rational(2, 21, 3)},
	})
	out.Write(ifd0)
	out.Write(exifIFD)
	out.Write(gpsIFD)
	return out.Bytes()
}

func buildExifJPEG(t *testing.T, dateTime, model string) []byte {
	var img bytes.Buffer
	if err := jpeg.Encode(&img, image.NewGray(image.Rect(0, 0, 8, 8)), nil); err != nil {
		t.Fatal(err)
	}
	payload := append([]byte("Exif\x00\x00"), buildTIFF(dateTime, model)...)
	var out bytes.Buffer
	out.Write([]byte{0xFF, 0xD8, 0xFF, 0xE1})
	out.Write(binary.BigEndian.AppendUint16(nil, uint16(len(payload)+2)))
	out.Write(payload)
	out.Write(img.Bytes()[2:]) // drop the encoder's SOI
	return out.Bytes()
}

func buildMP4(created time.Time, mdatSize int, moovFirst bool) []byte {
	be := binary.BigEndian
	box := func(typ string, body []byte) []byte {
		b := be.AppendUint32(nil, uint32(8+len(body)))
		b = append(b, typ...)
		return append(b, body...)
	}
	mvhd := make([]byte, 100)
	be.PutUint32(mvhd[4:8], uint32(created.Sub(mp4Epoch)/time.Second))
	moov := box("moov", box("mvhd", mvhd))
	ftyp := box("ftyp", []byte("isom\x00\x00\x02\x00isomiso2mp41"))
	mdat := box("mdat", make([]byte, mdatSize))
	if moovFirst {
		return bytes.Join([][]byte{ftyp, moov, mdat}, nil)
	}
	return bytes.Join([][]byte{ftyp, mdat, moov}, nil)
}
